            test("energy topology limit fails closed",new Runnable(){public void run(){setupEnergy();fluidNode(-1).energy.receive(1000,false);LegacyPL4.nodeLimit=2;check(fluidNode(0).transferOnce()==0&&fluidNode(-1).energy.stored()==1000,"oversized network");}});
            test("energy escrow drains without source",new Runnable(){public void run(){setupEnergy();fluidNode(0).energy.set(123);fluidAir(-1,200);check(fluidNode(0).transferOnce()==123&&fluidNode(3).energy.stored()==123&&fluidNode(0).energy.get()==0,"source-free flush");}});
